/// Fast binary search lookup in the global extension registry.
pub fn find_registered_format(ext: &str) -> Option<&'static str> {
    EXTENSION_REGISTRY
        .binary_search_by(|(registered_ext, _)| registered_ext.cmp(&ext))
        .ok()
        .map(|idx| EXTENSION_REGISTRY[idx].1)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_registry_is_strictly_sorted_without_duplicates() {
        for i in 1..EXTENSION_REGISTRY.len() {
            let prev = EXTENSION_REGISTRY[i - 1].0;
            let curr = EXTENSION_REGISTRY[i].0;
            assert!(
                prev < curr,
                "EXTENSION_REGISTRY violation: '{}' must be strictly less than '{}'",
                prev, curr
            );
        }
    }
}
